insert into sam_procedure_item (procedure_id, student_id, step_id, item_status, check_type, check_time, check_by, create_time)
values (#{procedureId}, #{studentId}, #{stepId}, '1', #{checkType}, #{checkTime}, #{checkBy}, #{checkTime})
